function MaxProduct(nums: int[]) -> int {
  let n = nums.length();
  let best = nums[0];
  let curMax = nums[0];
  let curMin = nums[0];
  let i = 1;
  while (i < n) {
    let x = nums[i];
    let a = curMax * x;
    let b = curMin * x;
    let newMax = x;
    if (a > newMax) {
      newMax = a;
    }
    if (b > newMax) {
      newMax = b;
    }
    let newMin = x;
    if (a < newMin) {
      newMin = a;
    }
    if (b < newMin) {
      newMin = b;
    }
    curMax = newMax;
    curMin = newMin;
    if (curMax > best) {
      best = curMax;
    }
    i += 1;
  }
  return best;
}
